import { QuadVerticiesArray, } from "../../../Mesher/Geometry/Geometry.types";
import { Matrix2x2Like, Vec2ArrayLike, AMath, } from "@amodx/math";
function getInterpolationWeights(x, y, flip = false) {
    x = Math.max(0, Math.min(1, x));
    y = Math.max(0, Math.min(1, y));
    let w1 = (1 - x) * (1 - y); // Weight for v1 = (0, 0)
    let w2 = x * (1 - y); // Weight for v2 = (1, 0)
    let w3 = x * y; // Weight for v3 = (1, 1)
    let w4 = (1 - x) * y; // Weight for v4 = (0, 1)
    return flip ? [w4, w3, w2, w1] : [w3, w4, w1, w2];
}
export function getVertexWeights(face, x, y, z) {
    let flip = false;
    let u, v;
    switch (face) {
        case 0 /* VoxelFaces.Up */:
            u = x;
            v = z;
            break;
        case 1 /* VoxelFaces.Down */:
            u = x;
            v = z;
            flip = true;
            break;
        case 2 /* VoxelFaces.North */:
            u = x;
            v = y;
            flip = true;
            break;
        case 3 /* VoxelFaces.South */:
            u = x;
            v = y;
            break;
        case 4 /* VoxelFaces.East */:
            u = z;
            v = y;
            break;
        case 5 /* VoxelFaces.West */:
            u = z;
            v = y;
            flip = true;
            break;
    }
    return getInterpolationWeights(u, v, flip);
}
export const getQuadWeights = (quad, direction) => {
    const returnArray = [];
    for (const vertex of QuadVerticiesArray) {
        const { x, y, z } = quad.positions.vertices[vertex];
        returnArray[vertex] = getVertexWeights(direction, x, y, z);
    }
    return returnArray;
};
const rotationMatrix = new Map();
export const mapQuadUvs = (uvs, rotation = 0, transform) => {
    if (transform.lockUVs == true) {
        let rotM = rotationMatrix.get(rotation);
        if (!rotM) {
            rotM = Matrix2x2Like.Rotation(AMath.DegreesToRadians(rotation));
            rotationMatrix.set(rotation, rotM);
        }
        return [
            Vec2ArrayLike.ApplyMatrix(rotM, [uvs[2], uvs[3]]),
            Vec2ArrayLike.ApplyMatrix(rotM, [uvs[0], uvs[3]]),
            Vec2ArrayLike.ApplyMatrix(rotM, [uvs[0], uvs[1]]),
            Vec2ArrayLike.ApplyMatrix(rotM, [uvs[2], uvs[1]]),
        ];
    }
    let u0 = uvs[0];
    let v0 = uvs[1];
    let u1 = uvs[2];
    let v1 = uvs[3];
    if (transform.flip) {
        if (transform.flip[0] === 1) {
            [u0, u1] = [u1, u0];
        }
        if (transform.flip[1] === 1) {
            [v0, v1] = [v1, v0];
        }
    }
    let quadUVs = [
        [u1, v1],
        [u0, v1],
        [u0, v0],
        [u1, v0],
    ];
    if (rotation !== 0) {
        let rotM = rotationMatrix.get(rotation);
        if (!rotM) {
            rotM = Matrix2x2Like.Rotation(AMath.DegreesToRadians(rotation));
            rotationMatrix.set(rotation, rotM);
        }
        const centerU = (u0 + u1) / 2;
        const centerV = (v0 + v1) / 2;
        quadUVs = quadUVs.map(([u, v]) => {
            let x = u - centerU;
            let y = v - centerV;
            [x, y] = Vec2ArrayLike.ApplyMatrix(rotM, [x, y]);
            x += centerU;
            y += centerV;
            return [x, y];
        });
    }
    return quadUVs;
};
